// DETERMINISTIC specification parsing. The source workflow this replaces used a
// web scraper plus an LLM to guess at endpoints; an OpenAPI document already
// states them exactly, so no model is involved in this step at all.
const req = $('Normalise Request').first().json;
const res = $json || {};
const status = Number(res.statusCode !== undefined ? res.statusCode : 200);

// The HTTP Request node returns different shapes depending on the response
// content type and on whether full-response mode is on, and an inline spec
// arrives differently again. Accept every shape rather than assuming one.
function pickPayload(r) {
  if (r && r.body !== undefined && r.body !== null && r.body !== '') { return r.body; }
  if (r && r.data !== undefined && r.data !== null && r.data !== '') { return r.data; }
  if (r && (r.paths || r.openapi || r.swagger)) { return r; }
  return null;
}

let spec = pickPayload(res);
let parseNote = null;

if (typeof spec === 'string') {
  const trimmed = spec.trim();
  try { spec = JSON.parse(trimmed); }
  catch (e) {
    return { json: { ok: false, status: status,
      error: 'specification body is a string but not valid JSON: ' + String(e.message || e) + '. YAML specifications are not supported; supply JSON.',
      goal: req.goal, source_workflow: req.source_workflow, started_at_ms: req.started_at_ms, max_probes: req.max_probes } };
  }
}

if (status < 200 || status >= 300) {
  return { json: { ok: false, status: status, error: 'could not load specification, HTTP ' + status,
    goal: req.goal, source_workflow: req.source_workflow, started_at_ms: req.started_at_ms, max_probes: req.max_probes } };
}

if (!spec || typeof spec !== 'object') {
  return { json: { ok: false, status: status,
    error: 'the response carried no usable specification payload. Observed item keys: [' + Object.keys(res).join(', ') + '], payload type: ' + (typeof spec),
    goal: req.goal, source_workflow: req.source_workflow, started_at_ms: req.started_at_ms, max_probes: req.max_probes } };
}

if (!spec.paths || typeof spec.paths !== 'object') {
  return { json: { ok: false, status: status,
    error: 'document has no paths object, so it is not an OpenAPI specification. Top-level keys: [' + Object.keys(spec).slice(0, 15).join(', ') + ']',
    goal: req.goal, source_workflow: req.source_workflow, started_at_ms: req.started_at_ms, max_probes: req.max_probes } };
}

// ---- Base URL -----------------------------------------------------------
let baseUrl = req.base_url_override || '';
if (!baseUrl) {
  const server = Array.isArray(spec.servers) && spec.servers.length ? String(spec.servers[0].url || '') : '';
  if (/^https?:\/\//i.test(server)) {
    baseUrl = server;
  } else if (server && req.spec_url) {
    const m = String(req.spec_url).match(/^(https?:\/\/[^\/]+)/i);
    baseUrl = m ? (m[1] + server) : '';
  }
}
baseUrl = baseUrl.replace(/\/+$/, '');

// ---- Authentication -----------------------------------------------------
const comps = spec.components || {};
const schemes = comps.securitySchemes || {};
const authSummary = Object.keys(schemes).map(function (k) {
  const s = schemes[k] || {};
  if (s.type === 'apiKey') { return k + ': apiKey in ' + s['in'] + ' named "' + s.name + '"'; }
  if (s.type === 'http') { return k + ': http ' + s.scheme + (s.bearerFormat ? ' (' + s.bearerFormat + ')' : ''); }
  if (s.type === 'oauth2') { return k + ': oauth2 with flows ' + Object.keys(s.flows || {}).join(', '); }
  if (s.type === 'openIdConnect') { return k + ': openIdConnect at ' + s.openIdConnectUrl; }
  return k + ': ' + (s.type || 'unknown');
});
const globalSecurity = Array.isArray(spec.security) ? spec.security.map(function (o) { return Object.keys(o).join('+'); }) : [];

// ---- Operations ---------------------------------------------------------
const METHODS = ['get', 'put', 'post', 'delete', 'patch', 'head', 'options'];
const READ_METHODS = ['get', 'head', 'options'];
const operations = [];

Object.keys(spec.paths).forEach(function (p) {
  const item = spec.paths[p] || {};
  const pathLevelParams = Array.isArray(item.parameters) ? item.parameters : [];
  METHODS.forEach(function (m) {
    const op = item[m];
    if (!op || typeof op !== 'object') { return; }
    const params = pathLevelParams.concat(Array.isArray(op.parameters) ? op.parameters : []);
    const required = params.filter(function (x) { return x && x.required; }).map(function (x) { return x['in'] + ':' + x.name; });
    const optional = params.filter(function (x) { return x && !x.required; }).map(function (x) { return x['in'] + ':' + x.name; });
    operations.push({
      operation_id: op.operationId || (m + ' ' + p),
      method: m.toUpperCase(),
      path: p,
      summary: (op.summary || op.description || '').slice(0, 180),
      required_params: required,
      optional_params: optional,
      has_request_body: !!op.requestBody,
      response_codes: Object.keys(op.responses || {}),
      security: Array.isArray(op.security) ? op.security.map(function (o) { return Object.keys(o).join('+'); }) : globalSecurity,
      write_effect: READ_METHODS.indexOf(m) === -1 ? 'write' : 'read',
      deprecated: !!op.deprecated
    });
  });
});

const digest = operations.map(function (o) {
  return o.operation_id + '  ' + o.method + ' ' + o.path +
    (o.required_params.length ? '  required=[' + o.required_params.join(', ') + ']' : '') +
    (o.optional_params.length ? '  optional=[' + o.optional_params.join(', ') + ']' : '') +
    (o.has_request_body ? '  body=yes' : '') +
    '  effect=' + o.write_effect +
    (o.summary ? '  -- ' + o.summary : '');
}).join('\n');

return {
  json: {
    ok: true,
    parse_note: parseNote,
    goal: req.goal,
    source_workflow: req.source_workflow,
    started_at_ms: req.started_at_ms,
    max_probes: req.max_probes,
    api_title: (spec.info && spec.info.title) || 'unknown',
    api_version: (spec.info && spec.info.version) || 'unknown',
    openapi_version: spec.openapi || spec.swagger || 'unknown',
    base_url: baseUrl,
    auth_summary: authSummary.length ? authSummary.join('; ') : 'no security schemes declared',
    auth_schemes: Object.keys(schemes),
    operation_count: operations.length,
    read_operation_count: operations.filter(function (o) { return o.write_effect === 'read'; }).length,
    write_operation_count: operations.filter(function (o) { return o.write_effect === 'write'; }).length,
    operation_ids: operations.map(function (o) { return o.operation_id; }),
    operations: operations,
    operations_digest: digest.slice(0, 20000)
  }
};

