// The single most valuable check in this workflow: every operationId the model
// proposed must exist in the parsed specification. This is exact set membership,
// so a hallucinated endpoint is caught with certainty rather than by opinion.
const spec = $('Parse OpenAPI Specification').first().json;
const raw = ($json && $json.json) ? $json.json : $json;

const byId = {};
(spec.operations || []).forEach(function (o) { byId[o.operation_id] = o; });

// Long structured responses get truncated mid-object often enough that discarding
// them outright throws away a usable plan. Close what is still open, drop any
// dangling partial member, and record that a repair happened.
function repairJson(text) {
  try { return { value: JSON.parse(text), repaired: false, error: null }; } catch (e) { /* fall through */ }

  const stack = [];
  let inStr = false;
  let esc = false;
  let lastTopLevelEnd = -1;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) { esc = false; }
      else if (c === '\\') { esc = true; }
      else if (c === '"') { inStr = false; }
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{' || c === '[') { stack.push(c); }
    else if (c === '}' || c === ']') { stack.pop(); if (stack.length === 0) { lastTopLevelEnd = i; } }
  }

  if (lastTopLevelEnd > 0) {
    try { return { value: JSON.parse(text.slice(0, lastTopLevelEnd + 1)), repaired: true, error: null }; } catch (e) { /* keep going */ }
  }

  let patched = text;
  if (inStr) { patched += '"'; }
  // Remove a trailing partial member such as  , "on_missing_fields": "half a sen
  patched = patched.replace(/,\s*"[^"]*"\s*:?\s*[^,{}\[\]]*$/, '');
  patched = patched.replace(/,\s*$/, '');
  for (let i = stack.length - 1; i >= 0; i--) { patched += (stack[i] === '{' ? '}' : ']'); }
  try { return { value: JSON.parse(patched), repaired: true, error: null }; } catch (e) {
    return { value: null, repaired: false, error: String(e.message || e) };
  }
}

let plan = null;
let parseError = null;
let planRepaired = false;
if (raw && raw.ok && raw.output) {
  const cleaned = String(raw.output).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  const r = repairJson(cleaned);
  plan = r.value;
  planRepaired = r.repaired;
  if (!plan) { parseError = r.error; }
} else {
  parseError = (raw && raw.error) ? String(raw.error) : 'model router returned no usable output';
}

const issues = [];
if (parseError) { issues.push({ code: 'plan_not_json', severity: 'critical', detail: parseError }); }
if (planRepaired) { issues.push({ code: 'plan_json_repaired', severity: 'medium', detail: 'the planner response was truncated or malformed and was repaired by closing unbalanced structures; later steps may have been lost' }); }

const steps = (plan && Array.isArray(plan.steps)) ? plan.steps : [];
const grounded = [];
const hallucinated = [];

steps.forEach(function (s, i) {
  const id = String(s.operation_id || '');
  const op = byId[id];
  if (!op) { hallucinated.push(id || '(step ' + (i + 1) + ' has no operation_id)'); return; }
  grounded.push({
    order: s.order || (i + 1),
    operation_id: id,
    method: op.method,
    path: op.path,
    purpose: s.purpose || null,
    inputs: Array.isArray(s.inputs) ? s.inputs : [],
    expected_response_fields: Array.isArray(s.expected_response_fields) ? s.expected_response_fields : [],
    on_missing_fields: s.on_missing_fields || null,
    write_effect: op.write_effect,
    model_claimed_effect: s.write_effect || null,
    effect_mismatch: (s.write_effect && s.write_effect !== op.write_effect) || false,
    required_params: op.required_params,
    risk_note: s.risk_note || null,
    deprecated: op.deprecated
  });
});

hallucinated.forEach(function (id) {
  issues.push({ code: 'hallucinated_operation', severity: 'critical', detail: 'plan references operationId "' + id + '" which does not exist in the specification' });
});
grounded.forEach(function (s) {
  if (s.effect_mismatch) {
    issues.push({ code: 'write_effect_mismatch', severity: 'high', detail: s.operation_id + ': model called it "' + s.model_claimed_effect + '" but the specification method ' + s.method + ' is a ' + s.write_effect });
  }
  if (s.deprecated) {
    issues.push({ code: 'deprecated_operation', severity: 'medium', detail: s.operation_id + ' is marked deprecated in the specification' });
  }
});

const readSteps = grounded.filter(function (s) { return s.write_effect === 'read'; });
const writeSteps = grounded.filter(function (s) { return s.write_effect === 'write'; });

return {
  json: {
    ok: !parseError && hallucinated.length === 0 && grounded.length > 0,
    plan_repaired: planRepaired,
    plan_summary: plan ? (plan.summary || null) : null,
    auth_requirements: plan && Array.isArray(plan.auth_requirements) ? plan.auth_requirements : [],
    open_questions: plan && Array.isArray(plan.open_questions) ? plan.open_questions : [],
    model_confidence: plan && typeof plan.confidence === 'number' ? plan.confidence : null,
    steps_proposed: steps.length,
    steps_grounded: grounded.length,
    hallucinated_operations: hallucinated,
    grounding_rate: steps.length ? Math.round((grounded.length / steps.length) * 100) / 100 : null,
    steps: grounded,
    read_steps: readSteps,
    write_steps: writeSteps,
    has_write_steps: writeSteps.length > 0,
    issues: issues,
    plan_json: plan ? JSON.stringify(plan) : null,
    router: { provider: raw ? raw.selected_provider : null, model: raw ? raw.selected_model : null, latency_ms: raw ? raw.latency_ms : null, estimated_cost_usd: raw ? raw.estimated_cost_usd : null }
  }
};

// Only read operations are ever probed, only against the base URL the
// specification itself declares, and only when the path needs no unknown
// parameters. Write steps never reach this node regardless of approval, because
// executing them is out of scope for a demonstration repository.
//
// Emits ONE container item, always. Returning an empty list here used to leave
// the downstream loop with nothing to do, and its done-branch never fired, so no
// integration report was produced at all.
const spec = $('Parse OpenAPI Specification').first().json;
const plan = $('Ground Plan Against Specification').first().json;
const maxProbes = Number(spec.max_probes || 2);

const probes = [];
const skipped = [];

if (!spec.base_url) {
  skipped.push('the specification declares no resolvable server URL');
} else if (maxProbes === 0) {
  skipped.push('max_probes is 0, so probing was disabled by the caller');
} else {
  (plan.read_steps || []).forEach(function (s) {
    if (probes.length >= maxProbes) { skipped.push(s.operation_id + ': probe budget of ' + maxProbes + ' already used'); return; }
    if (/\{[^}]+\}/.test(s.path)) { skipped.push(s.operation_id + ': path needs a template value that would have to be invented'); return; }
    const needsAuthParam = (s.required_params || []).some(function (p) { return /^(header|cookie):/.test(p); });
    if (needsAuthParam) { skipped.push(s.operation_id + ': requires a header or cookie parameter that is not available'); return; }
    const query = (s.required_params || [])
      .filter(function (p) { return p.indexOf('query:') === 0; })
      .map(function (p) { return p.slice(6) + '=available'; })
      .join('&');
    probes.push({
      operation_id: s.operation_id,
      method: s.method,
      path: s.path,
      url: spec.base_url + s.path + (query ? '?' + query : ''),
      expected_response_fields: s.expected_response_fields || []
    });
  });
  if (!(plan.read_steps || []).length) { skipped.push('the plan contains no read-only steps to probe'); }
}

return [{ json: { probe_count: probes.length, probes: probes, probes_skipped: skipped } }];

const spec = $('Parse OpenAPI Specification').first().json;
const plan = $('Ground Plan Against Specification').first().json;

function unwrap(n) {
  try { const v = $(n).first().json; return (v && v.json) ? v.json : v; } catch (e) { return null; }
}
const promptMeta = unwrap('Get Planner Prompt (08)');
const verification = unwrap('Verify Plan (09)');

let governance = null;
try { governance = $('Request Write Approval (05)').first().json; } catch (e) { governance = null; }
if (governance && governance.json) { governance = governance.json; }
if (!governance) { try { governance = $('No Write Steps to Approve').first().json; } catch (e) { governance = null; } }

const all = $input.all().map(function (i) { return i.json; });
const probes = all.filter(function (p) { return p && p.operation_id; });
const probeMeta = all.filter(function (p) { return p && p.probe_count !== undefined; })[0] || null;

const blocking = (plan.issues || []).filter(function (i) { return i.severity === 'critical'; });
const probesOk = probes.filter(function (p) { return p.ok; }).length;
const matched = probes.filter(function (p) { return p.schema_matches_plan; }).length;
const unverifiable = probes.filter(function (p) { return p.schema_unverifiable; }).length;

// Readiness is deliberately conservative: anything unproven counts against it.
const readiness = [];
readiness.push({ check: 'specification_parsed', passed: !!spec.ok, detail: spec.ok ? (spec.operation_count + ' operations parsed') : spec.error });
readiness.push({ check: 'plan_grounded_in_specification', passed: plan.hallucinated_operations.length === 0 && plan.steps_grounded > 0, detail: plan.steps_grounded + '/' + plan.steps_proposed + ' steps matched a real operationId' });
readiness.push({ check: 'plan_passed_verification', passed: !!(verification && verification.verified), detail: verification ? ('score ' + verification.score) : 'verification unavailable' });
readiness.push({ check: 'read_endpoints_reachable', passed: probes.length > 0 && probesOk === probes.length, detail: probesOk + '/' + probes.length + ' probes returned a 2xx' });
readiness.push({ check: 'response_schema_matched_plan', passed: probes.length > 0 && matched > 0 && (matched + unverifiable) === probes.length, detail: matched + ' matched, ' + unverifiable + ' had no checkable field spec, ' + (probes.length - matched - unverifiable) + ' mismatched' });
readiness.push({ check: 'write_steps_authorised', passed: !plan.has_write_steps || !!(governance && governance.approved), detail: plan.has_write_steps ? ('governance decision: ' + (governance ? governance.decision : 'unknown')) : 'no write steps in the plan' });
const readyCount = readiness.filter(function (r) { return r.passed; }).length;

return [{
  json: {
    generated_at: new Date().toISOString(),
    n8n_execution_id: $execution.id,
    goal: spec.goal,
    api: {
      title: spec.api_title, version: spec.api_version, openapi_version: spec.openapi_version,
      base_url: spec.base_url, operation_count: spec.operation_count,
      read_operations: spec.read_operation_count, write_operations: spec.write_operation_count,
      authentication: spec.auth_summary, auth_schemes: spec.auth_schemes
    },
    prompt: promptMeta ? { id: 'api-integration/spec-analyst', version: promptMeta.version, sha: promptMeta.sha, provenance: promptMeta.provenance, degraded: promptMeta.degraded } : null,
    model: plan.router,
    plan: {
      summary: plan.plan_summary,
      repaired: !!plan.plan_repaired,
      auth_requirements: plan.auth_requirements,
      open_questions: plan.open_questions,
      model_confidence: plan.model_confidence,
      steps_proposed: plan.steps_proposed,
      steps_grounded: plan.steps_grounded,
      grounding_rate: plan.grounding_rate,
      hallucinated_operations: plan.hallucinated_operations,
      steps: plan.steps
    },
    verification: verification ? {
      verified: verification.verified, score: verification.score,
      issues: verification.issues, requires_human_review: verification.requires_human_review
    } : { verified: false, score: null, issues: [{ code: 'verification_unavailable' }], requires_human_review: true },
    governance: governance ? {
      required: !!plan.has_write_steps, decision: governance.decision, approved: !!governance.approved,
      risk_level: governance.risk_level, reason: governance.decision_reason
    } : { required: !!plan.has_write_steps, decision: 'unknown', approved: false },
    probes: {
      attempted: probes.length, succeeded: probesOk, schema_matched: matched, schema_unverifiable: unverifiable,
      skipped: probeMeta ? probeMeta.probes_skipped : [],
      note: 'Only GET/HEAD operations against the base URL declared by the specification are probed. Write operations are never executed by this workflow, approved or not.',
      results: probes
    },
    issues: plan.issues,
    blocking_issues: blocking,
    readiness: { checks: readiness, passed: readyCount, total: readiness.length,
      verdict: readyCount === readiness.length ? 'ready_to_implement' : (blocking.length ? 'blocked' : 'needs_attention') },
    latency_ms: spec.started_at_ms ? (Date.now() - Number(spec.started_at_ms)) : null
  }
}];

// Compares the live response against the fields the plan said it expected.
// Reports what was actually observed rather than asserting the integration works.
const probe = $('Probe Loop').first().json;
const res = $json || {};
const status = Number(res.statusCode || 0);
const body = res.body;

function collectKeys(v, prefix, out, depth) {
  if (depth > 3 || out.length > 200) { return; }
  if (Array.isArray(v)) { if (v.length) { collectKeys(v[0], prefix, out, depth + 1); } return; }
  if (v && typeof v === 'object') {
    Object.keys(v).forEach(function (k) {
      const p = prefix ? (prefix + '.' + k) : k;
      out.push(p);
      collectKeys(v[k], p, out, depth + 1);
    });
  }
}
const keys = [];
collectKeys(body, '', keys, 0);

// Models describe response fields in several notations: 'rates.AUD', '$.rates',
// '[].id', 'data[].email'. Normalise those to a plain dotted path.
// They also sometimes write a prose DESCRIPTION instead of a path, such as
// '<currency_code>: <currency_name> (object mapping)'. That is not checkable,
// and counting it as a missing field would be a false positive, so it is
// reported separately instead.
const rawExpected = probe.expected_response_fields || [];
const checkable = [];
const unverifiable = [];

rawExpected.forEach(function (f) {
  const norm = String(f)
    .replace(/\[\d*\]/g, '')
    .replace(/^\$\.?/, '')
    .replace(/^\.+/, '')
    .replace(/\.+/g, '.')
    .trim();
  if (!norm) { return; }
  if (/^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$/.test(norm)) { checkable.push(norm); }
  else { unverifiable.push(String(f)); }
});

const missing = checkable.filter(function (f) {
  const leaf = f.split('.').pop();
  return !keys.some(function (k) {
    return k === f || k.endsWith('.' + f) || k.indexOf(f + '.') === 0 || k === leaf || k.endsWith('.' + leaf);
  });
});

const isArrayBody = Array.isArray(body);
const itemCount = isArrayBody ? body.length : (body && typeof body === 'object' ? 1 : 0);
const reachable = status >= 200 && status < 300;

return {
  json: {
    operation_id: probe.operation_id,
    method: probe.method,
    path: probe.path,
    url: probe.url,
    status_code: status,
    ok: reachable,
    response_shape: isArrayBody ? 'array' : (body && typeof body === 'object' ? 'object' : typeof body),
    item_count: itemCount,
    observed_fields: keys.slice(0, 40),
    expected_fields: checkable,
    unverifiable_field_specs: unverifiable,
    missing_expected_fields: missing,
    schema_matches_plan: reachable && checkable.length > 0 && missing.length === 0,
    schema_unverifiable: reachable && checkable.length === 0,
    error: status >= 400 ? ('endpoint returned HTTP ' + status) : (status === 0 ? 'request failed or timed out' : null)
  }
};
